-- Full schema for a fresh Supabase project (all migrations, in order).
-- Generated by scripts/frankfurt-migration/build-schema.sh — do not edit by hand.
-- Paste into the SQL editor of the NEW project and run once (choose "Run without RLS" if asked).

-- ===== 0001_init.sql =====
-- Y by Roy Oren — Phase 1 schema
--
-- Architecture note: all reads/writes go through the Next.js server using the
-- Supabase *service role* key (Server Components, Route Handlers, Server
-- Actions). The browser only talks to Supabase directly for anonymous auth
-- (to mint a durable cart session). Because of that, RLS is enabled on every
-- table with NO policies — the service role bypasses RLS entirely, and every
-- other role (anon/authenticated) is denied by default. This is intentional,
-- not an oversight: coupon codes, prices, and stock stay server-validated.

create extension if not exists pgcrypto;

-- ---------- products ----------
create table products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  description text not null default '',
  category text not null,
  allergens text not null default '',
  image_urls text[] not null default '{}',
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

create table product_sizes (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  label text not null,
  price_before_vat numeric(10,2) not null check (price_before_vat >= 0),
  stock_status text not null default 'in_stock' check (stock_status in ('in_stock', 'out_of_stock')),
  sort_order int not null default 0
);
create index product_sizes_product_id_idx on product_sizes(product_id);

-- ---------- coupons ----------
create table coupons (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  discount_pct numeric(4,3) not null check (discount_pct > 0 and discount_pct <= 1),
  active boolean not null default true,
  created_at timestamptz not null default now()
);

-- ---------- cart (server-side session cart, keyed by anonymous auth user) ----------
create table carts (
  id uuid primary key default gen_random_uuid(),
  session_user_id uuid not null unique,
  created_at timestamptz not null default now()
);

create table cart_items (
  id uuid primary key default gen_random_uuid(),
  cart_id uuid not null references carts(id) on delete cascade,
  product_size_id uuid not null references product_sizes(id) on delete cascade,
  qty int not null check (qty > 0),
  unique (cart_id, product_size_id)
);

-- ---------- orders (shop checkout) ----------
create table orders (
  id uuid primary key default gen_random_uuid(),
  cart_id uuid references carts(id) on delete set null,
  customer_name text not null,
  customer_email text not null,
  customer_phone text not null,
  pickup_date date not null,
  notes text not null default '',
  coupon_id uuid references coupons(id) on delete set null,
  subtotal numeric(10,2) not null,
  vat numeric(10,2) not null,
  discount numeric(10,2) not null default 0,
  total numeric(10,2) not null,
  status text not null default 'pending' check (status in ('pending', 'paid', 'cancelled')),
  grow_payment_id text,
  receipt_doc_id text,
  created_at timestamptz not null default now()
);

create table order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id) on delete cascade,
  product_name text not null,
  size_label text not null default '',
  unit_price numeric(10,2) not null,
  qty int not null check (qty > 0)
);
create index order_items_order_id_idx on order_items(order_id);

-- ---------- open meals ----------
create table meals (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text not null default '',
  date date not null,
  total_seats int not null check (total_seats > 0),
  price_per_seat numeric(10,2) not null check (price_per_seat >= 0),
  menu jsonb not null default '[]',
  status text not null default 'open' check (status in ('open', 'closed')),
  created_at timestamptz not null default now()
);

create table meal_registrations (
  id uuid primary key default gen_random_uuid(),
  meal_id uuid not null references meals(id) on delete cascade,
  customer_name text not null,
  customer_email text not null,
  customer_phone text not null,
  seats_count int not null check (seats_count > 0),
  deposit_total numeric(10,2) not null,
  status text not null default 'pending' check (status in ('pending', 'paid', 'cancelled')),
  grow_payment_id text,
  receipt_doc_id text,
  created_at timestamptz not null default now()
);
create index meal_registrations_meal_id_idx on meal_registrations(meal_id);

create table meal_diners (
  id uuid primary key default gen_random_uuid(),
  registration_id uuid not null references meal_registrations(id) on delete cascade,
  full_name text not null,
  dietary_restrictions text[] not null default '{}',
  notes text not null default ''
);
create index meal_diners_registration_id_idx on meal_diners(registration_id);

-- ---------- newsletter / contact ----------
create table newsletter_subscribers (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  source text not null check (source in ('footer', 'events_form')),
  created_at timestamptz not null default now()
);

create table contact_messages (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text not null,
  email text not null,
  message text not null,
  created_at timestamptz not null default now()
);

-- ---------- admin ----------
-- Phase 1: single owner. Phase 2 adds kitchen/sales roles and RLS keyed off `role`.
create table admin_profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  role text not null default 'owner' check (role in ('owner', 'kitchen', 'sales')),
  created_at timestamptz not null default now()
);

-- ---------- derived seat availability (always the real count; display tiering happens in app code) ----------
create view meal_availability as
select
  m.id as meal_id,
  m.total_seats,
  coalesce(sum(r.seats_count) filter (where r.status = 'paid'), 0)::int as taken_seats,
  m.total_seats - coalesce(sum(r.seats_count) filter (where r.status = 'paid'), 0)::int as remaining_seats
from meals m
left join meal_registrations r on r.meal_id = m.id
group by m.id, m.total_seats;

-- ---------- RLS: enabled everywhere, no policies (service role only) ----------
alter table products enable row level security;
alter table product_sizes enable row level security;
alter table coupons enable row level security;
alter table carts enable row level security;
alter table cart_items enable row level security;
alter table orders enable row level security;
alter table order_items enable row level security;
alter table meals enable row level security;
alter table meal_registrations enable row level security;
alter table meal_diners enable row level security;
alter table newsletter_subscribers enable row level security;
alter table contact_messages enable row level security;
alter table admin_profiles enable row level security;

-- ===== 0002_event_inquiries.sql =====
-- Phase 2: private events inquiry form (spec §6).
-- Same architecture as 0001_init.sql — RLS enabled, no policies, server-role only.

create table event_inquiries (
  id uuid primary key default gen_random_uuid(),
  event_type text not null,
  full_name text not null,
  phone text not null,
  email text not null,
  event_date date,
  start_time text,
  location_type text not null check (location_type in ('venue', 'other')),
  location_detail text not null default '',
  format text not null check (format in ('buffet', 'seated', 'other')),
  service_style text check (service_style in ('plated', 'family')),
  guest_count int not null check (guest_count >= 10),
  details text not null default '',
  newsletter_opt_in boolean not null default false,
  status text not null default 'new' check (status in ('new', 'contacted', 'quoted', 'closed')),
  created_at timestamptz not null default now()
);

alter table event_inquiries enable row level security;

-- ===== 0003_admin_enhancements.sql =====
-- Product lead time (days notice required before a pickup date can be selected).
alter table products add column lead_time_days int not null default 0 check (lead_time_days >= 0);

-- More granular private-event inquiry statuses, alongside the original four.
alter table event_inquiries drop constraint event_inquiries_status_check;
alter table event_inquiries add constraint event_inquiries_status_check
  check (status in ('new', 'contacted', 'quoted', 'approved_unpaid', 'deposit_paid', 'paid_closed', 'closed'));

-- ===== 0004_media_and_team.sql =====
-- Public storage bucket for product photos, page carousels, and the About
-- hero image. Public bucket = publicly readable object URLs without an RLS
-- policy; uploads/deletes still only ever happen via the service role from
-- the Next.js server, consistent with every other table in this project.
insert into storage.buckets (id, name, public)
values ('images', 'images', true)
on conflict (id) do nothing;

-- Generic gallery/hero images not tied to a specific product or meal —
-- used for the meals-page carousel, the events-page carousel, and the
-- About-page hero photo.
create table site_media (
  id uuid primary key default gen_random_uuid(),
  location text not null check (location in ('meals_carousel', 'events_carousel', 'about_hero')),
  image_url text not null,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

alter table site_media enable row level security;

-- ===== 0005_kitchen_ledger.sql =====
-- "Kitchen Ledger" — internal back-office system for recipe costing, prep
-- planning, and event production (distinct from the customer-facing shop
-- orders / meal registrations / event inquiries elsewhere in this schema).
-- All tables prefixed kl_ to avoid any naming collision with those.
--
-- Same architecture as the rest of the project: RLS enabled, no policies —
-- every read/write goes through the Next.js server via the service role.

create table kl_suppliers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  note text not null default '',
  created_at timestamptz not null default now()
);

create table kl_equipment (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  note text not null default '',
  created_at timestamptz not null default now()
);

create table kl_guests (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text not null default '',
  restrictions text not null default '',
  created_at timestamptz not null default now()
);

create table kl_ingredients (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  unit text not null,
  supplier_id uuid references kl_suppliers(id) on delete set null,
  purchase_name text not null default '',
  purchase_unit text not null default '',
  yield_percent numeric(5,2) check (yield_percent is null or (yield_percent > 0 and yield_percent <= 100)),
  price numeric(12,5),
  created_at timestamptz not null default now()
);
create index kl_ingredients_supplier_id_idx on kl_ingredients(supplier_id);

create table kl_recipes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  type text not null check (type in ('dish', 'prep')),
  base_amount numeric(12,3) not null check (base_amount > 0),
  base_unit text not null,
  prep_steps jsonb not null default '[]',       -- [{ id, text }]
  prep_equipment jsonb not null default '[]',    -- [{ equipId, qty }] — home prep only, not taken to events
  event_equipment jsonb not null default '[]',   -- [{ equipId, qty }] — taken to events
  created_at timestamptz not null default now()
);

-- Many-to-many self-referential component list. A recipe's ingredients and
-- nested-recipe children live here (kind discriminates which FK is set).
create table kl_recipe_components (
  id uuid primary key default gen_random_uuid(),
  recipe_id uuid not null references kl_recipes(id) on delete cascade,
  kind text not null check (kind in ('ingredient', 'recipe')),
  ingredient_id uuid references kl_ingredients(id) on delete cascade,
  component_recipe_id uuid references kl_recipes(id) on delete cascade,
  amount numeric(12,3) not null check (amount > 0),
  sort_order int not null default 0,
  check (
    (kind = 'ingredient' and ingredient_id is not null and component_recipe_id is null) or
    (kind = 'recipe' and component_recipe_id is not null and ingredient_id is null)
  )
);
create index kl_recipe_components_recipe_id_idx on kl_recipe_components(recipe_id);
create index kl_recipe_components_component_recipe_id_idx on kl_recipe_components(component_recipe_id);

create table kl_events (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  date date,
  event_type text not null check (event_type in ('onsite', 'offsite')),
  location text not null default '',
  guest_count int not null default 0 check (guest_count >= 0),
  notes text not null default '',
  created_at timestamptz not null default now()
);

create table kl_event_menu (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references kl_events(id) on delete cascade,
  recipe_id uuid not null references kl_recipes(id) on delete cascade,
  servings numeric(12,3) not null check (servings > 0),
  sort_order int not null default 0
);
create index kl_event_menu_event_id_idx on kl_event_menu(event_id);

-- One row per seat (0-indexed up to guest_count - 1). guest_id null = unassigned.
create table kl_event_guest_seats (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references kl_events(id) on delete cascade,
  seat_index int not null,
  guest_id uuid references kl_guests(id) on delete set null,
  unique (event_id, seat_index)
);

-- Checkbox state for an event's prep tree / shopping list, persisted so the
-- whole team sees the same state (refresh-to-sync, per the v1 scope).
create table kl_event_completed_items (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references kl_events(id) on delete cascade,
  item_key text not null,   -- e.g. "recipe:<id>", "step:<recipeId>:<stepId>", "shopping:<ingredientId>"
  created_at timestamptz not null default now(),
  unique (event_id, item_key)
);

alter table kl_suppliers enable row level security;
alter table kl_equipment enable row level security;
alter table kl_guests enable row level security;
alter table kl_ingredients enable row level security;
alter table kl_recipes enable row level security;
alter table kl_recipe_components enable row level security;
alter table kl_events enable row level security;
alter table kl_event_menu enable row level security;
alter table kl_event_guest_seats enable row level security;
alter table kl_event_completed_items enable row level security;

-- ===== 0006_greeting_card_and_supplier_contact.sql =====
-- Greeting card add-on for shop orders
alter table orders
  add column greeting_card_message text,
  add column greeting_card_fee numeric(10,2) not null default 0;

alter table orders
  add constraint orders_greeting_card_message_length
  check (greeting_card_message is null or char_length(greeting_card_message) <= 200);

-- Supplier contact details
alter table kl_suppliers
  add column phone text not null default '',
  add column email text not null default '';

-- ===== 0007_meal_diner_controls.sql =====
-- Per-diner deposit tracking, decoupled from registration-level Grow status,
-- so admins can move/split diners between meals and mark manually-collected
-- deposits (e.g. paid in person, not through the site) independently of the
-- online payment flow.
alter table meal_diners
  add column deposit_paid boolean not null default false;

-- Backfill: diners already tied to a paid registration are considered paid.
update meal_diners d
set deposit_paid = true
from meal_registrations r
where d.registration_id = r.id and r.status = 'paid';

-- Seat occupancy now reflects actual confirmed diners rather than whole-registration
-- status, so partially-paid groups and moved/split diners are counted correctly.
create or replace view meal_availability as
select
  m.id as meal_id,
  m.total_seats,
  coalesce(count(d.id) filter (where d.deposit_paid and r.status <> 'cancelled'), 0)::int as taken_seats,
  m.total_seats - coalesce(count(d.id) filter (where d.deposit_paid and r.status <> 'cancelled'), 0)::int as remaining_seats
from meals m
left join meal_registrations r on r.meal_id = m.id
left join meal_diners d on d.registration_id = r.id
group by m.id, m.total_seats;

-- ===== 0008_product_i18n_and_categories.sql =====
-- Bilingual product fields (English is optional — falls back to Hebrew
-- wherever it's empty, so existing products don't break).
alter table products add column name_en text;
alter table products add column description_en text;
alter table products add column allergens_en text;

-- Categories become an admin-managed table instead of a hardcoded list, so
-- the owner can add new ones without a code change. products.category keeps
-- storing the slug string (unchanged), now backed by a real FK.
create table categories (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  label_he text not null,
  label_en text not null,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

insert into categories (slug, label_he, label_en, sort_order) values
  ('desserts', 'קינוחים', 'Desserts', 0),
  ('spreads', 'ממרחים', 'Spreads', 1),
  ('frozen', 'קפואים', 'Frozen', 2),
  ('pasta', 'פסטה', 'Pasta', 3);

alter table products
  add constraint products_category_fkey foreign key (category) references categories(slug);

-- ===== 0009_home_carousel_location.sql =====
-- The site_media.location CHECK constraint predates the home page carousel
-- feature, so every upload with location='home_carousel' was silently
-- rejected by Postgres (the app never surfaced the DB error to the admin).
alter table site_media drop constraint site_media_location_check;
alter table site_media add constraint site_media_location_check
  check (location in ('meals_carousel', 'events_carousel', 'about_hero', 'home_carousel'));

-- ===== 0010_security_advisor_fixes.sql =====
-- categories was added in 0008 without RLS, unlike every other table
-- (see the "RLS: enabled everywhere, no policies" block in 0001_init.sql).
-- No policies needed: the app only ever reads/writes it via the
-- service-role client, which bypasses RLS regardless.
alter table categories enable row level security;

-- meal_availability runs as its owner by default, so it can bypass RLS on
-- meals/meal_registrations for anyone querying it directly (e.g. via the
-- public anon key over PostgREST). security_invoker makes it run as the
-- querying role instead, so an anon caller gets nothing while the
-- service-role client (which bypasses RLS either way) is unaffected.
alter view meal_availability set (security_invoker = true);

-- ===== 0011_coupon_limits_order_fulfillment_notifications.sql =====
-- ---------- coupon usage limits (single-use / limited count / unlimited) ----------
alter table coupons add column usage_limit_type text not null default 'unlimited'
  check (usage_limit_type in ('single', 'limited', 'unlimited'));
alter table coupons add column usage_limit_count integer
  check (usage_limit_count is null or usage_limit_count > 0);
alter table coupons add column times_used integer not null default 0;
alter table coupons add constraint coupons_limit_count_required_when_limited check (
  usage_limit_type <> 'limited' or usage_limit_count is not null
);

-- ---------- order fulfillment status ----------
-- Separate from `status` (pending/paid/cancelled, which gates payment and
-- receipt logic and must not change meaning). This tracks the kitchen/pickup
-- workflow for an already-paid order.
alter table orders add column fulfillment_status text not null default 'open'
  check (fulfillment_status in ('open', 'prepared', 'completed', 'partially_fulfilled', 'no_show'));

-- ---------- admin notification recipients ----------
-- Replaces the single ADMIN_NOTIFICATION_EMAIL env var with an
-- admin-manageable list, each subscribed per notification type.
create table notification_recipients (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  notify_shop_order boolean not null default true,
  notify_event_inquiry boolean not null default true,
  notify_meal_registration boolean not null default true,
  notify_contact_message boolean not null default true,
  created_at timestamptz not null default now()
);
alter table notification_recipients enable row level security;

-- ===== 0012_order_payment_method_and_manual_entry.sql =====
-- How a paid order was actually paid — null until marked paid (or for older
-- rows, "website" backfilled below since that's the only channel that
-- existed before this migration).
alter table orders add column payment_method text
  check (payment_method is null or payment_method in ('website', 'credit_card', 'bit', 'paybox', 'cash', 'bank_transfer'));

update orders set payment_method = 'website' where status = 'paid';

-- orders.cart_id is already nullable (on delete set null, no not-null), so
-- admin-entered phone/in-person orders can leave it null with no schema change.

-- Add "awaiting_payment" as a selectable prep status (distinct from the
-- payment `status` column, which still gates webhook/receipt logic).
alter table orders drop constraint orders_fulfillment_status_check;
alter table orders add constraint orders_fulfillment_status_check check (
  fulfillment_status in ('awaiting_payment', 'open', 'prepared', 'completed', 'partially_fulfilled', 'no_show')
);

-- ===== 0013_recipe_bring_offsite.sql =====
-- Per-component "taken to offsite events" flag, plus free-text bring items per
-- recipe. Both feed the "items and preps to bring" list of an offsite event.
--
-- bring_offsite defaults to true on purpose: until now every direct child of
-- a dish (raw ingredient or prep) was brought to offsite events, so existing
-- recipes keep producing the same list until someone unticks an item.
alter table kl_recipe_components add column bring_offsite boolean not null default true;

-- [{ id, text }] — free-form extras to take (e.g. "disposable cutlery"),
-- not tied to any ingredient.
alter table kl_recipes add column bring_items jsonb not null default '[]';

-- ===== 0014_recipe_self_bring_offsite.sql =====
-- Whether the dish/prep ITSELF goes on an offsite event's "items and preps to
-- bring" list when it is on the event's menu. (Its components have their own
-- flags, kl_recipe_components.bring_offsite, so e.g. the finished dish can stay
-- home while some ingredients still travel.)
-- Defaults to true: menu dishes already appear on that list today.
alter table kl_recipes add column bring_offsite boolean not null default true;

-- ===== 0015_product_and_size_ordering.sql =====
-- Owner-chosen order for products in the shop, for the sizes within a product,
-- and a per-product "default size" (the one preselected in the shop), which no
-- longer has to be the first one in the list.

alter table product_sizes add column if not exists is_default boolean not null default false;

-- Until now sort_order was 0 everywhere, so the order was whatever the
-- database returned. Number the existing rows (oldest first) so every product
-- and size gets a distinct position and the current order is kept.
update products p
set sort_order = r.rn
from (
  select id, row_number() over (order by sort_order, created_at) - 1 as rn
  from products
) r
where p.id = r.id;

update product_sizes s
set sort_order = r.rn
from (
  select id, row_number() over (partition by product_id order by sort_order, ctid) - 1 as rn
  from product_sizes
) r
where s.id = r.id;

-- ===== 0016_allergen_tags.sql =====
-- Allergens become an owner-managed list of colored tags instead of free text:
-- the owner builds the list once, picks tags per product, and the shop can
-- filter by them. The old free-text products.allergens / allergens_en columns
-- stay in place (no longer used) so nothing is lost.

create table allergens (
  id uuid primary key default gen_random_uuid(),
  label_he text not null,
  label_en text not null default '',
  color text not null default '#c9923a',
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

create table product_allergens (
  product_id uuid not null references products(id) on delete cascade,
  allergen_id uuid not null references allergens(id) on delete cascade,
  primary key (product_id, allergen_id)
);

alter table allergens enable row level security;
alter table product_allergens enable row level security;

-- Starter list (the owner can edit, recolor, delete or add more).
insert into allergens (label_he, label_en, color, sort_order) values
  ('גלוטן', 'Gluten', '#c9923a', 0),
  ('ביצים', 'Eggs', '#d9ae2f', 1),
  ('חלב', 'Milk', '#4f86c6', 2),
  ('לקטוז', 'Lactose', '#7aa7d9', 3),
  ('אגוזים', 'Nuts', '#8b5a3c', 4),
  ('בוטנים', 'Peanuts', '#b0703c', 5),
  ('סויה', 'Soy', '#6f9a4d', 6),
  ('שומשום', 'Sesame', '#a89463', 7),
  ('פרג', 'Poppy seeds', '#6b4f8a', 8),
  ('קוקוס', 'Coconut', '#3f8f8b', 9);

-- Tag existing products from their old free-text allergen list.
insert into product_allergens (product_id, allergen_id)
select p.id, a.id
from products p
join allergens a on position(a.label_he in p.allergens) > 0
on conflict do nothing;

-- ===== 0017_product_categories.sql =====
-- A product can now sit in several shop categories. The join table is the
-- source of truth; products.category is left in place as a legacy column
-- (no longer required, no longer a foreign key, no longer read or written).

create table product_categories (
  product_id uuid not null references products(id) on delete cascade,
  category_id uuid not null references categories(id) on delete cascade,
  primary key (product_id, category_id)
);

alter table product_categories enable row level security;

-- Every product keeps the category it had.
insert into product_categories (product_id, category_id)
select p.id, c.id
from products p
join categories c on c.slug = p.category
on conflict do nothing;

-- Deleting a category must always be possible (its products just lose that tag).
alter table products drop constraint if exists products_category_fkey;
alter table products alter column category drop not null;

-- ===== 0018_category_colors.sql =====
-- Each shop category gets a color (shown on the category labels over product photos).
alter table categories add column if not exists color text not null default '#efe8d8';

-- ===== 0019_seat_count_includes_unpaid.sql =====
-- The public seat meter should count everyone who is registered, not only
-- diners whose deposit is marked paid (same count the admin panel shows).
--
-- One exception: a website checkout that was started but never paid is not
-- allowed to hold seats forever. Such a registration only counts for 30
-- minutes after it was created (time to finish paying). Registrations
-- entered or touched by the owner in the admin panel always count.

alter table meal_registrations
  add column source text not null default 'web' check (source in ('web', 'admin'));

-- Registrations the owner entered by hand (no deposit expected from the site).
update meal_registrations set source = 'admin' where status = 'pending' and deposit_total = 0;

create or replace view meal_availability as
select
  m.id as meal_id,
  m.total_seats,
  coalesce(count(d.id) filter (where r.status <> 'cancelled' and (
    d.deposit_paid
    or r.status = 'paid'
    or r.source = 'admin'
    or r.created_at > now() - interval '30 minutes'
  )), 0)::int as taken_seats,
  m.total_seats - coalesce(count(d.id) filter (where r.status <> 'cancelled' and (
    d.deposit_paid
    or r.status = 'paid'
    or r.source = 'admin'
    or r.created_at > now() - interval '30 minutes'
  )), 0)::int as remaining_seats
from meals m
left join meal_registrations r on r.meal_id = m.id
left join meal_diners d on d.registration_id = r.id
group by m.id, m.total_seats;

alter view meal_availability set (security_invoker = true);

-- ===== 0020_analytics_and_audit_log.sql =====
-- ===== First-party, cookie-less site analytics =====
-- One row per event sent by the browser tracker (components/site/Analytics.tsx)
-- or recorded on the server. No IP address and no persistent identifier is
-- stored: session_id lives in the tab's sessionStorage, visitor_hash is a daily
-- rotating hash computed on the server.

create table analytics_events (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  session_id text not null,
  visitor_hash text,
  type text not null,
  path text,
  locale text,
  referrer_host text,
  utm_source text,
  utm_medium text,
  utm_campaign text,
  device text,
  browser text,
  os text,
  country text,
  value numeric,
  props jsonb not null default '{}'::jsonb,
  dedupe_key text unique
);

create index analytics_events_created_idx on analytics_events (created_at);
create index analytics_events_type_created_idx on analytics_events (type, created_at);
create index analytics_events_session_idx on analytics_events (session_id);

alter table analytics_events enable row level security;

-- ===== Admin audit log: who did what in the admin panel =====
create table admin_audit_log (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  admin_id uuid,
  admin_email text,
  admin_role text,
  action text not null,
  entity_type text,
  entity_id text,
  entity_label text,
  changes jsonb,
  ip text,
  user_agent text
);

create index admin_audit_log_created_idx on admin_audit_log (created_at desc);
create index admin_audit_log_admin_idx on admin_audit_log (admin_email, created_at desc);

alter table admin_audit_log enable row level security;

-- ===== Dashboard numbers, computed in one call =====
-- p_from / p_to are the range (to is exclusive). Days are bucketed in Israel time.
create or replace function analytics_summary(p_from timestamptz, p_to timestamptz)
returns jsonb
language sql
stable
as $$
with ev as (
  select * from analytics_events where created_at >= p_from and created_at < p_to
),
pv as (select * from ev where type = 'pageview'),
sess as (
  select
    session_id,
    count(*) as pageviews,
    (array_agg(coalesce(nullif(utm_source, ''), nullif(referrer_host, ''), 'direct') order by created_at))[1] as source,
    (array_agg(device order by created_at))[1] as device,
    (array_agg(browser order by created_at))[1] as browser,
    (array_agg(country order by created_at))[1] as country,
    (array_agg(locale order by created_at))[1] as locale,
    (array_agg(path order by created_at))[1] as landing,
    (array_agg(path order by created_at desc))[1] as exit_path
  from pv
  group by session_id
),
dur as (
  select session_id, sum(value) as ms from ev where type = 'page_leave' group by session_id
),
purchased as (select distinct session_id from ev where type = 'purchase'),
carted as (select distinct session_id from ev where type = 'add_to_cart'),
days as (
  select d::date as day
  from generate_series(
    (p_from at time zone 'Asia/Jerusalem')::date,
    ((p_to - interval '1 second') at time zone 'Asia/Jerusalem')::date,
    interval '1 day'
  ) d
),
daily as (
  select
    (created_at at time zone 'Asia/Jerusalem')::date as day,
    count(*) as pageviews,
    count(distinct session_id) as sessions,
    count(distinct visitor_hash) as visitors
  from pv
  group by 1
),
step as (
  select
    count(distinct session_id) filter (where type = 'pageview' and path ~ '^(/en)?/shop') as shop_visit,
    count(distinct session_id) filter (where type = 'product_view') as product_view,
    count(distinct session_id) filter (where type = 'add_to_cart') as add_to_cart,
    count(distinct session_id) filter (where type = 'checkout_start') as checkout_start,
    count(distinct session_id) filter (where type = 'checkout_submit') as checkout_submit,
    count(distinct session_id) filter (where type = 'purchase') as purchase,
    count(distinct session_id) filter (where type = 'pageview' and path ~ '^(/en)?/meals') as meals_visit,
    count(distinct session_id) filter (where type = 'meal_register_open') as meal_register_open,
    count(distinct session_id) filter (where type = 'meal_register_submit') as meal_register_submit,
    count(distinct session_id) filter (where type = 'meal_paid') as meal_paid,
    count(distinct session_id) filter (where type = 'pageview' and path ~ '^(/en)?/events') as events_visit,
    count(distinct session_id) filter (where type = 'event_inquiry_open') as event_inquiry_open,
    count(distinct session_id) filter (where type = 'event_inquiry_submit') as event_inquiry_submit,
    count(distinct session_id) filter (where type = 'pageview' and path ~ '^(/en)?/contact') as contact_visit,
    count(distinct session_id) filter (where type = 'contact_submit') as contact_submit,
    count(distinct session_id) filter (where type = 'newsletter_signup') as newsletter_signup
  from ev
)
select jsonb_build_object(
  'totals', (
    select jsonb_build_object(
      'sessions', (select count(*) from sess),
      'visitors', (select count(distinct visitor_hash) from pv),
      'pageviews', (select count(*) from pv),
      'avg_duration_ms', (select coalesce(avg(coalesce(dur.ms, 0)), 0) from sess left join dur using (session_id)),
      'bounce_sessions', (select count(*) from sess where pageviews = 1),
      'purchase_sessions', (select count(*) from sess join purchased using (session_id)),
      'cart_sessions', (select count(*) from sess join carted using (session_id)),
      'abandoned_cart_sessions', (select count(*) from carted c where not exists (select 1 from purchased p where p.session_id = c.session_id))
    )
  ),
  'active_now', (select count(distinct session_id) from analytics_events where created_at > now() - interval '5 minutes'),
  'daily', (
    select coalesce(jsonb_agg(jsonb_build_object(
      'day', days.day,
      'pageviews', coalesce(daily.pageviews, 0),
      'sessions', coalesce(daily.sessions, 0),
      'visitors', coalesce(daily.visitors, 0)
    ) order by days.day), '[]'::jsonb)
    from days left join daily using (day)
  ),
  'hourly', (
    select coalesce(jsonb_agg(jsonb_build_object('hour', h, 'pageviews', coalesce(c, 0)) order by h), '[]'::jsonb)
    from generate_series(0, 23) h
    left join (
      select extract(hour from created_at at time zone 'Asia/Jerusalem')::int as hr, count(*) as c from pv group by 1
    ) x on x.hr = h
  ),
  'weekday', (
    select coalesce(jsonb_agg(jsonb_build_object('dow', w, 'pageviews', coalesce(c, 0)) order by w), '[]'::jsonb)
    from generate_series(0, 6) w
    left join (
      select extract(dow from created_at at time zone 'Asia/Jerusalem')::int as dw, count(*) as c from pv group by 1
    ) x on x.dw = w
  ),
  'pages', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select
        pv.path,
        count(*) as views,
        count(distinct pv.session_id) as sessions,
        (select avg(value) from ev l where l.type = 'page_leave' and l.path = pv.path) as avg_ms,
        (select avg((l.props->>'scroll')::numeric) from ev l where l.type = 'page_leave' and l.path = pv.path and l.props ? 'scroll') as avg_scroll,
        (select count(*) from sess s where s.exit_path = pv.path) as exits,
        (select count(*) from sess s where s.landing = pv.path) as entrances
      from pv
      group by pv.path
      order by views desc
      limit 30
    ) t
  ),
  'sources', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select
        s.source,
        count(*) as sessions,
        count(*) filter (where exists (select 1 from carted c where c.session_id = s.session_id)) as carts,
        count(*) filter (where exists (select 1 from purchased p where p.session_id = s.session_id)) as purchases
      from sess s
      group by s.source
      order by sessions desc
      limit 15
    ) t
  ),
  'devices', (select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (select coalesce(device, 'unknown') as name, count(*) as sessions from sess group by 1 order by 2 desc) t),
  'browsers', (select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (select coalesce(browser, 'unknown') as name, count(*) as sessions from sess group by 1 order by 2 desc limit 8) t),
  'countries', (select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (select coalesce(country, 'unknown') as name, count(*) as sessions from sess group by 1 order by 2 desc limit 10) t),
  'locales', (select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (select coalesce(locale, 'unknown') as name, count(*) as sessions from sess group by 1 order by 2 desc) t),
  'funnels', (select to_jsonb(step) from step),
  'products', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select
        coalesce(props->>'name', props->>'slug') as name,
        count(*) filter (where type = 'product_view') as views,
        count(*) filter (where type = 'add_to_cart') as carts
      from ev
      where type in ('product_view', 'add_to_cart') and coalesce(props->>'name', props->>'slug') is not null
      group by 1
      order by views desc, carts desc
      limit 20
    ) t
  ),
  'sold', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select oi.product_name as name, sum(oi.qty)::int as qty, sum(oi.qty * oi.unit_price) as revenue
      from order_items oi
      join orders o on o.id = oi.order_id
      where o.status = 'paid' and o.created_at >= p_from and o.created_at < p_to
      group by oi.product_name
      order by revenue desc
      limit 20
    ) t
  ),
  'revenue', jsonb_build_object(
    'orders', (select count(*) from orders where status = 'paid' and created_at >= p_from and created_at < p_to),
    'orders_total', (select coalesce(sum(total), 0) from orders where status = 'paid' and created_at >= p_from and created_at < p_to),
    'meal_registrations', (select count(*) from meal_registrations where status = 'paid' and created_at >= p_from and created_at < p_to),
    'meal_deposits', (select coalesce(sum(deposit_total), 0) from meal_registrations where status = 'paid' and created_at >= p_from and created_at < p_to)
  ),
  'clicks', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select props->>'label' as label, props->>'kind' as kind, count(*) as clicks
      from ev
      where type = 'click' and coalesce(props->>'label', '') <> ''
      group by 1, 2
      order by clicks desc
      limit 25
    ) t
  ),
  'filters', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select props->>'filter' as filter, props->>'value' as value, count(*) as uses
      from ev
      where type = 'filter_use'
      group by 1, 2
      order by uses desc
      limit 20
    ) t
  ),
  'errors', (
    select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) from (
      select props->>'message' as message, path, count(*) as occurrences
      from ev
      where type = 'js_error'
      group by 1, 2
      order by occurrences desc
      limit 10
    ) t
  )
);
$$;

-- ===== 0021_invoice_items_and_event_cost_snapshot.sql =====
-- ===== Kitchen: prices are entered once per invoice item =====
-- An invoice item is one thing bought from a supplier, priced exactly as on the
-- invoice (net, per purchase unit: kg, cob, sack...). Each kl_ingredients row is
-- one "form" of it (peeled, sliced...) with its own amount per purchase unit and
-- its own yield. kl_ingredients.price stays the per-unit price the cost engine reads;
-- it is now computed: price_net / units_per_purchase_unit. Nothing in the cost
-- formula changes, and existing ingredients keep exactly the price they have.

create table kl_invoice_items (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  supplier_id uuid references kl_suppliers(id) on delete set null,
  purchase_unit text not null default '',
  price_net numeric(16,8),
  vat_rate numeric(5,2) not null default 18 check (vat_rate >= 0 and vat_rate < 100),
  invoice_date date,
  invoice_no text not null default '',
  note text not null default '',
  price_updated_at timestamptz,
  created_at timestamptz not null default now(),
  legacy_ingredient_id uuid
);
create index kl_invoice_items_supplier_id_idx on kl_invoice_items(supplier_id);
alter table kl_invoice_items enable row level security;

alter table kl_ingredients
  add column invoice_item_id uuid references kl_invoice_items(id) on delete set null,
  add column units_per_purchase_unit numeric(16,5) not null default 1 check (units_per_purchase_unit > 0);
create index kl_ingredients_invoice_item_id_idx on kl_ingredients(invoice_item_id);

-- Room for prices that are small per gram (price / 1000 etc.) without rounding.
alter table kl_ingredients alter column price type numeric(16,8);

-- Every existing ingredient becomes one invoice item with one form, same price.
insert into kl_invoice_items (name, supplier_id, purchase_unit, price_net, legacy_ingredient_id)
select
  coalesce(nullif(trim(i.purchase_name), ''), i.name),
  i.supplier_id,
  coalesce(nullif(trim(i.purchase_unit), ''), i.unit),
  i.price,
  i.id
from kl_ingredients i
where i.invoice_item_id is null;

update kl_ingredients i
set invoice_item_id = it.id
from kl_invoice_items it
where it.legacy_ingredient_id = i.id and i.invoice_item_id is null;

alter table kl_invoice_items drop column legacy_ingredient_id;

-- ingredient.price (per measure unit) always follows its invoice item.
create or replace function kl_ingredient_apply_invoice_price() returns trigger
language plpgsql as $$
begin
  if new.invoice_item_id is not null then
    select
      case when it.price_net is null then null else it.price_net / new.units_per_purchase_unit end,
      it.supplier_id
    into new.price, new.supplier_id
    from kl_invoice_items it
    where it.id = new.invoice_item_id;
  end if;
  return new;
end $$;

create trigger kl_ingredient_apply_invoice_price_trg
before insert or update of invoice_item_id, units_per_purchase_unit on kl_ingredients
for each row execute function kl_ingredient_apply_invoice_price();

create or replace function kl_invoice_item_stamp() returns trigger
language plpgsql as $$
begin
  if new.price_net is distinct from old.price_net then
    new.price_updated_at := now();
  end if;
  return new;
end $$;

create trigger kl_invoice_item_stamp_trg
before update on kl_invoice_items
for each row execute function kl_invoice_item_stamp();

create or replace function kl_invoice_item_propagate() returns trigger
language plpgsql as $$
begin
  update kl_ingredients e
  set price = case when new.price_net is null then null else new.price_net / e.units_per_purchase_unit end,
      supplier_id = new.supplier_id
  where e.invoice_item_id = new.id;
  return null;
end $$;

create trigger kl_invoice_item_propagate_trg
after update of price_net, supplier_id on kl_invoice_items
for each row execute function kl_invoice_item_propagate();

-- ===== Events: cost frozen when the event is closed =====
alter table kl_events
  add column closed_at timestamptz,
  add column cost_snapshot jsonb;

-- ===== 0022_meal_seats_display.sql =====
-- Per-meal control of how seats are shown on the public meals page: the text and the
-- meter are set independently. These only change what is displayed, never the real
-- seat counts, with one exception: text mode 'full' closes registration for the meal.

alter table meals
  add column seats_text_mode text not null default 'auto'
    check (seats_text_mode in ('auto', 'open', 'few', 'exact', 'full', 'custom', 'hidden')),
  add column seats_text_he text not null default '',
  add column seats_text_en text not null default '',
  add column seats_meter_mode text not null default 'auto'
    check (seats_meter_mode in ('auto', 'real', 'hidden'));

-- ===== 0023_stock_and_daily_limits.sql =====
-- Per-product limits for the shop.
--   * products.daily_limit: the most units of the product (all sizes together) that can be
--     picked up on one date. NULL = no limit.
--   * product_sizes.stock_qty: units left in stock "as of" stock_as_of. Orders placed after that
--     moment use it up; at 0 the size shows as sold out. NULL = no stock limit.

alter table products
  add column daily_limit int check (daily_limit is null or daily_limit > 0);

alter table product_sizes
  add column stock_qty int check (stock_qty is null or stock_qty >= 0),
  add column stock_as_of timestamptz;

-- Orders remember which size each line was, so limits and stock can be counted.
alter table order_items
  add column product_size_id uuid references product_sizes(id) on delete set null;
create index order_items_product_size_id_idx on order_items(product_size_id);

-- Orders entered by the owner always hold their units; website checkouts that were
-- started but not paid only hold them for 30 minutes.
alter table orders
  add column source text not null default 'web' check (source in ('web', 'admin'));

-- Units left per size (only for sizes that have a stock quantity). May go below 0 if oversold.
create or replace view product_size_stock as
select
  s.id as product_size_id,
  s.stock_qty - coalesce((
    select sum(oi.qty)
    from order_items oi
    join orders o on o.id = oi.order_id
    where oi.product_size_id = s.id
      and o.created_at >= coalesce(s.stock_as_of, '-infinity'::timestamptz)
      and (o.status = 'paid' or (o.status = 'pending' and (o.source = 'admin' or o.created_at > now() - interval '30 minutes')))
  ), 0)::int as remaining
from product_sizes s
where s.stock_qty is not null;

-- Units of each product already taken for each pickup date (all sizes together).
create or replace view product_day_usage as
select
  s.product_id,
  o.pickup_date,
  sum(oi.qty)::int as qty
from order_items oi
join orders o on o.id = oi.order_id
join product_sizes s on s.id = oi.product_size_id
where o.status = 'paid' or (o.status = 'pending' and (o.source = 'admin' or o.created_at > now() - interval '30 minutes'))
group by s.product_id, o.pickup_date;

alter view product_size_stock set (security_invoker = true);
alter view product_day_usage set (security_invoker = true);

-- ===== 0024_recipe_total_grams.sql =====
-- Total weight (in grams) a recipe yields, next to its base amount / base unit
-- (e.g. 10 servings that come to 1500 g). Used for the cost per gram.
alter table kl_recipes
  add column total_grams numeric(12,3) check (total_grams is null or total_grams > 0);

-- ===== 0025_recipe_portions_precision.sql =====
-- A recipe's base amount is now derived from grams / portions (e.g. 1000 g in 150 g portions = 6.666667
-- portions), so it needs more decimals than 3.
alter table kl_recipes
  alter column base_amount type numeric(14,6);

-- ===== 0026_recipe_sale_calculator.sql =====
-- Per-recipe "sold in the shop" pricing calculator. Kept on the recipe screen only (not read by the shop).
-- sale_variants: [{ id, grams, extras: [{ id, name, cost }], mode, salePrice, foodCostPct }]
alter table kl_recipes add column sold_in_store boolean not null default false;
alter table kl_recipes add column sale_variants jsonb not null default '[]';

